let total = 0;
function add(n) { total += n; return total; }

// pure
function addPure(total, n) {
  return total + n;
}

const nums = [1, 2, 3, 4];
const sumSquares = nums
  .filter((n) => n % 2 === 0)
  .map((n) => n * n)
  .reduce((a, n) => a + n, 0);

function withRetry(fn, times = 3) {
  return async function retried(...args) {
    let lastError;
    for (let i = 0; i < times; i++) {
      try {
        return await fn(...args);
      } catch (err) {
        lastError = err;
      }
    }
    throw lastError;
  };
}

const curryAdd = (a) => (b) => a + b;
const add5 = curryAdd(5);
add5(3); // 8

function partial(fn, ...preset) {
  return (...rest) => fn(...preset, ...rest);
}
